def calculate_minimum_passengers():
    n = int(input())
    A = list(map(int, input().split()))

    current_passengers = 0
    min_passengers = 0

    for i in A:
        current_passengers += i
        if current_passengers < 0:
            min_passengers = max(min_passengers, -current_passengers)

    print(min_passengers)
